        assertThat(read(replay)).isEqualTo(read(first));
        MvcResult oldDetail = mvc.perform(get("/api/v1/plans/{key}", oldKey))
                .andExpect(status().isOk()).andReturn();
        assertThat(read(oldDetail).get("status").asText()).isEqualTo("CANCELLED");
