{"cmd": "$enc = New-Object System.Text.UTF8Encoding($false)
$base = (Get-Location).Path
$dir = "$base\src\main\java\com\example\starter\plan\web\dto"
$files = @{}
$files['RegisterRestrictionRequest.java'] = @'
package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import java.time.Instant;

/**
 * 限速令登记请求。requestKey 为幂等键；指纹包含区段、时段、速度与操作者。
 * sectionId/startUtc/endUtc/maxSpeedKmh 的非法取值由服务层判定并返回 422。
 */
public record RegisterRestrictionRequest(
        @NotBlank String requestKey,
        @NotBlank String restrictionKey,
        String sectionId,
        Instant startUtc,
        Instant endUtc,
        Integer maxSpeedKmh,
        @NotBlank String operator) {
}
'@
$files['AmendRestrictionRequest.java'] = @'
package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.Instant;

/**
 * 限速令修订请求：按 expectedVersion 乐观校验，成功版本加一。
 * 修订不改写已生成的重排记录。requestKey 为幂等键。
 */
public record AmendRestrictionRequest(
        @NotBlank String requestKey,
        @NotNull Integer expectedVersion,
        String sectionId,
        Instant startUtc,
        Instant endUtc,
        Integer maxSpeedKmh,
        @NotBlank String operator) {
}
'@
$files['RevokeRestrictionRequest.java'] = @'
package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 限速令撤销请求。requestKey 为幂等键；撤销后限速令不再影响后续发布或改签。
 */
public record RevokeRestrictionRequest(
        @NotBlank String requestKey,
        @NotBlank String operator) {
}
'@
$files['RestrictionResponse.java'] = @'
package com.example.starter.plan.web.dto;

import java.time.Instant;

/**
 * 限速令视图。createdAt/updatedAt/revokedAt 为 UTC 毫秒时间戳；
 * revokedAt 为 null 表示未撤销。
 */
public record RestrictionResponse(
        String restrictionKey,
        int version,
        String sectionId,
        Instant startUtc,
        Instant endUtc,
        int maxSpeedKmh,
        String status,
        String operator,
        long createdAt,
        long updatedAt,
        Long revokedAt) {
}
'@
$files['RearrangeRecordView.java'] = @'
package com.example.starter.plan.web.dto;

import java.time.Instant;

/**
 * 限速重排记录视图（不可变历史证据）。createdAt 为 UTC 毫秒时间戳；
 * 各时刻字段为 UTC 瞬时，区间左闭右开。
 */
public record RearrangeRecordView(
        String scheduleKey,
        String restrictionKey,
        int restrictionVersion,
        String sectionId,
        int maxSpeedKmh,
        Instant restrictionStartUtc,
        Instant restrictionEndUtc,
        int seq,
        String trainNo,
        Instant originalStartUtc,
        Instant originalEndUtc,
        Instant shiftedStartUtc,
        Instant shiftedEndUtc,
        int shiftMinutes,
        int affectedMinutes,
        long createdAt) {
}
'@
$files['EffectiveSpeedView.java'] = @'
package com.example.starter.plan.web.dto;

import java.time.Instant;
import java.util.List;

/**
 * 区段在指定时刻的生效限速诊断视图（只读）。
 * effectiveSpeedKmh 为该时刻所有生效限速令的最低速度；无生效限速令时为 null。
 */
public record EffectiveSpeedView(
        String sectionId,
        Instant at,
        Integer effectiveSpeedKmh,
        List<RestrictionResponse> activeRestrictions) {
}
'@
foreach ($k in $files.Keys) { [System.IO.File]::WriteAllText("$dir\$k", $files[$k], $enc) }
Write-Output "done""}

